#!/usr/bin/env node
// Submit responses generated by a repository fixture. No adapter or action readback is claimed.
import { randomUUID } from "node:crypto";
import { appendFile, readFile, stat } from "node:fs/promises";

if (process.argv.includes("--help")) {
  console.log("Set RELEASEPROOF_TOKEN, RP_ARTIFACT_FILE and RP_GITHUB_*; then run: node releaseproof-repository-check.mjs");
  process.exit(0);
}
if (process.argv.length !== 2) throw new Error("Run without arguments, or use --help.");
for (const name of ["RELEASEPROOF_TOKEN", "RP_ARTIFACT_FILE", "RP_GITHUB_REPOSITORY", "RP_GITHUB_PR_NUMBER", "RP_GITHUB_BASE_SHA", "RP_GITHUB_HEAD_SHA"]) {
  if (!process.env[name]) throw new Error(`${name} is required.`);
}
const origin = new URL(process.env.RELEASEPROOF_URL || "https://releaseproof-lake.vercel.app/");
if (origin.protocol !== "https:" || origin.username || origin.password || origin.pathname !== "/" || origin.search || origin.hash) {
  throw new Error("RELEASEPROOF_URL must be the HTTPS origin of ReleaseProof.");
}
const github = {
  repository: process.env.RP_GITHUB_REPOSITORY,
  pullRequest: Number(process.env.RP_GITHUB_PR_NUMBER),
  baseSha: process.env.RP_GITHUB_BASE_SHA,
  headSha: process.env.RP_GITHUB_HEAD_SHA,
};
if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(github.repository)
  || !Number.isSafeInteger(github.pullRequest) || github.pullRequest < 1
  || !/^[a-f0-9]{40}$/.test(github.baseSha) || !/^[a-f0-9]{40}$/.test(github.headSha)) {
  throw new Error("GitHub pull request context is incomplete or invalid.");
}
const file = process.env.RP_ARTIFACT_FILE;
if ((await stat(file)).size > 1_000_000) throw new Error("Repository artifact exceeds 1 MB.");
const artifact = JSON.parse(await readFile(file, "utf8"));
if (!artifact || artifact.schemaVersion !== 1 || artifact.kind !== "agency-assistant-scenario-run"
  || artifact.mode !== "repository" || artifact.backendOrigin || !Array.isArray(artifact.scenarios)
  || !Array.isArray(artifact.results) || artifact.scenarios.length < 1 || artifact.scenarios.length > 12
  || artifact.scenarios.some((scenario) => !Array.isArray(scenario.expectedEvents) || scenario.expectedEvents.length
    || !Array.isArray(scenario.requirementIds) || scenario.requirementIds.length !== 1)
  || artifact.results.some((result) => !Array.isArray(result.events) || result.events.length
    || !Array.isArray(result.eventTypes) || result.eventTypes.length || result.leadCount || result.bookingCount)) {
  throw new Error("Repository artifact must contain only text replies and no action claims.");
}
artifact.github = github; // The trusted workflow provides PR identity, never the candidate artifact.
const headers = {
  authorization: `Bearer ${process.env.RELEASEPROOF_TOKEN}`,
  ...(process.env.VERCEL_AUTOMATION_BYPASS_SECRET ? { "x-vercel-protection-bypass": process.env.VERCEL_AUTOMATION_BYPASS_SECRET } : {}),
};
async function requestJson(url, options = {}) {
  const response = await fetch(url, {
    method: options.method || "GET", redirect: "error", signal: AbortSignal.timeout(options.timeout || 20_000),
    headers: { accept: "application/json", ...headers, ...(options.body ? { "content-type": "application/json" } : {}) },
    ...(options.body ? { body: JSON.stringify(options.body) } : {}),
  });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${options.label || "Request"} failed (HTTP ${response.status})${typeof body?.error === "string" ? `: ${body.error}` : "."}`);
  if (!body || typeof body !== "object") throw new Error(`${options.label || "Request"} returned invalid JSON.`);
  return body;
}
const project = await requestJson(new URL("/api/cli-project", origin), { label: "Project setup" });
if (project.schemaVersion !== 1 || project.protocol !== "releaseproof-agency-v1"
  || project.mode !== "repository" || project.backendOrigin || project.reportCredits === 0) {
  throw new Error("The project is not ready or has no report credits.");
}
const checkId = randomUUID();
console.log(`ReleaseProof check ID: ${checkId}`);
async function recover() {
  const url = new URL("/api/cli-reports", origin);
  url.searchParams.set("checkId", checkId);
  for (let attempt = 0; attempt < 4; attempt++) {
    try { return await requestJson(url, { label: "Saved report lookup", timeout: 10_000 }); }
    catch (error) { if (!/HTTP 404/.test(String(error))) break; }
    if (attempt < 3) await new Promise((resolve) => setTimeout(resolve, 2_000));
  }
  return null;
}
let report;
try {
  report = await requestJson(new URL("/api/evaluate", origin), {
    method: "POST", body: { artifact, checkId }, timeout: 95_000, label: "ReleaseProof evaluation",
  });
} catch (error) {
  report = await recover();
  if (!report) throw error;
}
if (!report.persistence?.runId || !report.summary) throw new Error("ReleaseProof did not return a saved report.");
const reportUrl = new URL(`/history/${report.persistence.runId}`, origin);
console.log(`Report: ${reportUrl}`);
console.log(`A ${report.summary.versionAScore}/100; B ${report.summary.versionBScore}/100; regressions ${report.summary.regressions}; recommendation ${report.summary.recommendation}.`);
if (process.env.GITHUB_STEP_SUMMARY) {
  const cell = (value) => String(value ?? "").replace(/\|/g, "\\|").replace(/[\r\n]+/g, " ");
  const rows = (report.cases ?? []).map((item) => `| ${cell(item.category)} | ${cell(item.verdict)} | ${cell(item.versionAScore)} | ${cell(item.versionBScore)} |`);
  await appendFile(process.env.GITHUB_STEP_SUMMARY, [
    "## ReleaseProof · repository responses", "",
    `[${cell(github.repository)} · PR #${github.pullRequest}](https://github.com/${github.repository}/pull/${github.pullRequest}) · [candidate ${github.headSha.slice(0, 7)}](https://github.com/${github.repository}/commit/${github.headSha})`, "",
    `[Open private report](${reportUrl})`, "",
    "Responses were generated by this repository's test fixture. ReleaseProof did not independently verify external actions or live market state.", "",
    `A ${report.summary.versionAScore}/100 · B ${report.summary.versionBScore}/100 · ${report.summary.regressions} regressions · ${cell(report.summary.recommendation)}`, "",
    "| Scenario | Verdict | A | B |", "| --- | --- | ---: | ---: |", ...rows, "",
  ].join("\n"), { mode: 0o600 });
}
if (report.summary.recommendation !== "ship" || report.summary.regressions > 0) process.exitCode = 1;
